# Manual trace / cross-check of each row's classification and the dedup logic
import csv, json, re
from datetime import date
from decimal import Decimal, ROUND_HALF_UP

rates = {k.upper(): Decimal(str(v)) for k, v in json.load(open('/data/rates.json')).items()}
rates['USD'] = Decimal('1')
amount_re = re.compile(r'^\d+(\.\d{1,2})?$')

def parse_date(s):
    s = s.strip()
    try:
        if re.fullmatch(r'\d{4}-\d{2}-\d{2}', s):
            y,m,d = map(int, s.split('-')); return date(y,m,d)
        if re.fullmatch(r'\d{2}/\d{2}/\d{4}', s):
            m,d,y = map(int, s.split('/')); return date(y,m,d)
    except ValueError: return None
    return None

last = {}
print(f"{'ln':>3} {'oid':>6} {'verdict':<28} detail")
for lineno, row in enumerate(csv.reader(open('/data/sales.csv', newline='')), 1):
    if lineno == 1 or not row: continue
    oid, dts, region, currency, amount, status = row
    amt_clean = amount.replace(',', '')
    a_ok = bool(amount_re.fullmatch(amt_clean.strip()))
    c_ok = currency.strip().upper() in rates
    dt = parse_date(dts)
    if not (a_ok and c_ok and dt):
        why = []
        if not a_ok: why.append('bad-amt')
        if not c_ok: why.append('bad-cur')
        if dt is None: why.append('bad-date')
        print(f"{lineno:>3} {oid:>6} {'REJECT':<28} {'+'.join(why)}")
        continue
    last[oid] = (lineno, dt, region.strip().capitalize(), currency.strip().upper(), Decimal(amt_clean.strip()), status.strip().lower())

print("\n--- after dedup (last occurrence kept) ---")
agg = {}
for oid, (lineno, dt, reg, cur, amt, st) in last.items():
    kept = st=='paid' and dt.year==2026 and dt.month==3
    tag = 'COUNTS' if kept else ('skip:'+('not-paid' if st!='paid' else 'not-Mar2026'))
    usd = (amt*rates[cur]).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) if kept else None
    if kept:
        a = agg.setdefault(reg,[0,Decimal(0)]); a[0]+=1; a[1]+=usd
    print(f"oid {oid:>6} ln{lineno:>3} {dt} {reg:<7} {cur} {amt} {st:<9} -> {tag} {usd if usd else ''}")

print("\n--- totals ---")
for reg,(c,r) in sorted(agg.items(), key=lambda kv:(-kv[1][1],kv[0])):
    print(f"{reg:<8} {c} {r}")
PYEOF
